@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap');

:root {
  --bg-primary: #0F0F0F;
  --bg-secondary: #161625;
  --bg-tertiary: #1C1C2E;
  --bg-card: #1A1A2E;
  --bg-hover: #252540;
  --bg-input: #1E1E35;
  --border: #2A2A45;
  --border-light: #333355;
  --text-primary: #E8E8F0;
  --text-secondary: #9E9EBF;
  --text-muted: #6B6B8D;
  --accent: #2962FF;
  --accent-hover: #3D73FF;
  --accent-muted: rgba(41, 98, 255, 0.15);
  --green: #22C55E;
  --green-bg: rgba(34, 197, 94, 0.1);
  --green-border: rgba(34, 197, 94, 0.25);
  --red: #F7525F;
  --red-bg: rgba(247, 82, 95, 0.1);
  --red-border: rgba(247, 82, 95, 0.25);
  --yellow: #EAB308;
  --orange: #F97316;
  --platinum: #E5E4E2;
  --gold: #FFD700;
  --radius: 8px;
  --radius-lg: 12px;
  --radius-sm: 4px;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  min-height: 100vh;
}

a { color: var(--accent); text-decoration: none; transition: color 0.15s; }
a:hover { color: var(--accent-hover); }

/* Scrollbar */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--bg-secondary); }
::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--border-light); }

/* Navigation */
.nav {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 100;
}
.nav-inner {
  max-width: 1400px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  padding: 0 24px;
  height: 56px;
  gap: 32px;
}
.nav-logo {
  font-size: 20px;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -0.5px;
  display: flex;
  align-items: center;
  gap: 8px;
  white-space: nowrap;
}
.nav-logo .logo-icon {
  width: 28px;
  height: 28px;
  background: var(--accent);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  color: #fff;
  font-weight: 800;
}
.nav-links {
  display: flex;
  gap: 4px;
  list-style: none;
}
.nav-links a {
  color: var(--text-secondary);
  padding: 8px 14px;
  border-radius: var(--radius);
  font-size: 14px;
  font-weight: 500;
  transition: all 0.15s;
  white-space: nowrap;
}
.nav-links a:hover,
.nav-links a.active {
  color: var(--text-primary);
  background: var(--bg-hover);
}
.nav-right {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 12px;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 8px 20px;
  border-radius: var(--radius);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: all 0.15s;
  white-space: nowrap;
}
.btn-primary {
  background: var(--accent);
  color: #fff;
}
.btn-primary:hover { background: var(--accent-hover); }
.btn-outline {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--border);
}
.btn-outline:hover { border-color: var(--border-light); background: var(--bg-hover); }
.btn-ghost {
  background: transparent;
  color: var(--text-secondary);
  padding: 6px 12px;
}
.btn-ghost:hover { color: var(--text-primary); background: var(--bg-hover); }
.btn-sm { padding: 4px 12px; font-size: 12px; }

/* Tabs */
.tabs {
  display: flex;
  gap: 2px;
  border-bottom: 1px solid var(--border);
  margin-bottom: 16px;
}
.tab {
  padding: 10px 16px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-muted);
  cursor: pointer;
  border-bottom: 2px solid transparent;
  transition: all 0.15s;
  white-space: nowrap;
  background: none;
  border-top: none;
  border-left: none;
  border-right: none;
}
.tab:hover { color: var(--text-secondary); }
.tab.active {
  color: var(--text-primary);
  border-bottom-color: var(--accent);
}

/* Cards */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
}
.card-header {
  padding: 16px 20px;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.card-body { padding: 16px 20px; }

/* Badge */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
}
.badge-green { background: var(--green-bg); color: var(--green); border: 1px solid var(--green-border); }
.badge-red { background: var(--red-bg); color: var(--red); border: 1px solid var(--red-border); }
.badge-blue { background: var(--accent-muted); color: var(--accent); border: 1px solid rgba(41, 98, 255, 0.25); }
.badge-neutral { background: var(--bg-hover); color: var(--text-secondary); border: 1px solid var(--border); }
.badge-platinum { background: rgba(229,228,226,0.1); color: var(--platinum); border: 1px solid rgba(229,228,226,0.25); }
.badge-gold { background: rgba(255,215,0,0.1); color: var(--gold); border: 1px solid rgba(255,215,0,0.25); }

/* Tables */
.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}
.data-table th {
  padding: 10px 12px;
  text-align: left;
  font-weight: 600;
  color: var(--text-muted);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-bottom: 1px solid var(--border);
}
.data-table td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
  color: var(--text-primary);
}
.data-table tr:last-child td { border-bottom: none; }
.data-table tr:hover td { background: var(--bg-hover); }
.data-table .text-green { color: var(--green); }
.data-table .text-red { color: var(--red); }
.data-table .text-muted { color: var(--text-muted); }
.data-table .text-secondary { color: var(--text-secondary); }
.data-table .font-mono { font-variant-numeric: tabular-nums; }

/* Accordion */
.accordion-item {
  border-bottom: 1px solid var(--border);
}
.accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 12px;
  cursor: pointer;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  background: none;
  border: none;
  width: 100%;
  text-align: left;
  transition: color 0.15s;
}
.accordion-header:hover { color: var(--text-secondary); }
.accordion-header .chevron {
  transition: transform 0.2s;
  font-size: 10px;
}
.accordion-item.open .accordion-header .chevron { transform: rotate(180deg); }
.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.25s ease;
}
.accordion-item.open .accordion-body {
  max-height: 500px;
}

/* Sparkline canvas */
.sparkline { display: block; }

/* Market summary bar */
.market-summary-bar {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  overflow-x: auto;
}
.market-summary-inner {
  display: flex;
  gap: 24px;
  padding: 10px 24px;
  max-width: 1400px;
  margin: 0 auto;
  min-width: max-content;
}
.market-index {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 13px;
  white-space: nowrap;
}
.market-index-name {
  color: var(--text-muted);
  font-weight: 500;
}
.market-index-price {
  color: var(--text-primary);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.market-index-change {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

/* Container */
.container { max-width: 1400px; margin: 0 auto; padding: 0 24px; }

/* Section */
.section { padding: 40px 0; }
.section-title {
  font-size: 20px;
  font-weight: 700;
  margin-bottom: 20px;
  color: var(--text-primary);
}

/* Footer */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border);
  padding: 48px 0 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 32px;
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 24px;
}
.footer-col h4 {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 16px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.footer-col a {
  display: block;
  color: var(--text-muted);
  font-size: 13px;
  padding: 4px 0;
  transition: color 0.15s;
}
.footer-col a:hover { color: var(--text-primary); }
.footer-bottom {
  margin-top: 40px;
  padding-top: 24px;
  border-top: 1px solid var(--border);
  text-align: center;
  color: var(--text-muted);
  font-size: 12px;
  max-width: 1400px;
  margin-left: auto;
  margin-right: auto;
  padding-left: 24px;
  padding-right: 24px;
}

/* Toggle switch */
.toggle-wrapper {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--text-secondary);
  cursor: pointer;
}
.toggle {
  width: 36px;
  height: 20px;
  background: var(--border);
  border-radius: 10px;
  position: relative;
  transition: background 0.2s;
  cursor: pointer;
}
.toggle::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 16px;
  height: 16px;
  background: var(--text-primary);
  border-radius: 50%;
  transition: transform 0.2s;
}
.toggle.active { background: var(--accent); }
.toggle.active::after { transform: translateX(16px); }

/* Rating stars */
.stars { color: var(--yellow); font-size: 14px; letter-spacing: 1px; }

/* Responsive */
@media (max-width: 768px) {
  .nav-inner { padding: 0 16px; gap: 16px; }
  .nav-links { display: none; }
  .container { padding: 0 16px; }
  .section { padding: 24px 0; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .market-summary-inner { padding: 8px 16px; gap: 16px; }
}

/* Animations */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}
.fade-in { animation: fadeIn 0.3s ease; }

/* Chart page layout */
.chart-layout {
  display: grid;
  grid-template-columns: 240px 1fr 320px;
  height: calc(100vh - 56px);
}
.chart-sidebar {
  background: var(--bg-secondary);
  border-right: 1px solid var(--border);
  overflow-y: auto;
}
.chart-main {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.chart-detail {
  background: var(--bg-secondary);
  border-left: 1px solid var(--border);
  overflow-y: auto;
}

@media (max-width: 1024px) {
  .chart-layout {
    grid-template-columns: 1fr;
    grid-template-rows: auto 1fr auto;
  }
  .chart-sidebar, .chart-detail { display: none; }
}

/* Idea cards grid */
.ideas-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 16px;
}

/* Broker cards */
.broker-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 20px;
  display: flex;
  align-items: center;
  gap: 20px;
  transition: border-color 0.15s;
}
.broker-card:hover { border-color: var(--border-light); }

